import os from "os";
import type { ErrorLike, ParsedErrorPayload, RequestLike } from "./types";
import {
  classifyError,
  determineSeverity,
  extractRequestContext,
  generateFingerprint,
} from "./utils";

interface ParserOptions {
  service: string;
  environment: string;
  version?: string;
  release?: string;
  commitHash?: string;
  branch?: string;
  buildId?: string;
  deploymentId?: string;
}

function normalizeError(error: unknown): Error {
  if (error instanceof Error) return error;
  const fallback = new Error(String(error));
  if (typeof error === "object" && error !== null) {
    const candidate = error as ErrorLike;
    if (candidate.name) fallback.name = candidate.name;
    if (candidate.stack) fallback.stack = candidate.stack;
  }
  return fallback;
}

const parseError = (error: unknown, req?: RequestLike, options?: ParserOptions): ParsedErrorPayload => {
  try {
    const normalizedError = normalizeError(error);

    const fingerprint = generateFingerprint(normalizedError);
    const errorType = classifyError(normalizedError);
    const severity = determineSeverity(normalizedError);

    return {
      message: normalizedError.message || "Unknown error",
      name: normalizedError.name || "Error",
      stack: normalizedError.stack ?? "",
      fingerprint,
      timestamp: Date.now(),

      service_id: "unknown-service",
      environment: "unknown-mode",
      version: options?.version,
      release: options?.release,
      commitHash: options?.commitHash,
      branch: options?.branch,
      buildId: options?.buildId,
      deploymentId: options?.deploymentId,

      severity,
      errorType,

      serviceContext: {
        pid: process.pid,
        runtime: "node",
        runtimeVersion: process.version,
        nodeVersion: process.version,
        platform: process.platform,
        hostname: os.hostname(),
      },

    requestContext: extractRequestContext(req) ?? undefined,
    };
  } catch (parseError) {
    const parserFailure =
      parseError instanceof Error ? parseError.message : "Unknown parser failure";
    return {
      message: `Parser failure: ${parserFailure}`,
      name: "ParserError",
      stack: "",
      fingerprint: "unknown",
      timestamp: Date.now(),

      service_id: "unknown-service",
      environment: "unknown-mode",
      version: options?.version,
      release: options?.release,
      commitHash: options?.commitHash,
      branch: options?.branch,
      buildId: options?.buildId,
      deploymentId: options?.deploymentId,

      severity: "critical",
      errorType: "UNKNOWN",

      serviceContext: {
        pid: process.pid,
        runtime: "node",
        runtimeVersion: process.version,
        nodeVersion: process.version,
        platform: process.platform,
        hostname: os.hostname(),
      },

      requestContext: undefined,
    };
  }
};

export { parseError };
