import crypto from "crypto";
import type { ErrorType, RequestContext, RequestLike, Severity } from "../types";
import { sanitizeHeaders, sanitizeValue } from "./sanitize";

const generateFingerprint = (error: Error): string => {
  const stackLine = error.stack?.split("\n")[1] || "";
  return crypto
    .createHash("sha256")
    .update(error.message + stackLine)
    .digest("hex");
};

const classifyError = (error: Error): ErrorType => {
  const msg = error.message.toLowerCase();

  if (
    msg.includes("timeout") ||
    msg.includes("econnrefused") ||
    msg.includes("database") ||
    msg.includes("sql")
  ) {
    return "DATABASE";
  }

  if (
    msg.includes("network") ||
    msg.includes("fetch") ||
    msg.includes("socket")
  ) {
    return "NETWORK";
  }

  if (
    error.name === "ValidationError" ||
    msg.includes("validation")
  ) {
    return "VALIDATION";
  }

  if (
    msg.includes("permission") ||
    msg.includes("denied") ||
    msg.includes("forbidden") ||
    msg.includes("unauthorized") ||
    msg.includes("jwt")
  ) {
    return "AUTH";
  }

  if (error instanceof Error) {
    return "RUNTIME";
  }

  return "UNKNOWN";
};

const determineSeverity = (error: Error): Severity => {
  const msg = error.message.toLowerCase();

  if (
    msg.includes("database") ||
    msg.includes("timeout") ||
    msg.includes("econnrefused")
  ) {
    return "critical";
  }

  return "medium";
};

const normalizeHeader = (value: string | string[] | undefined): string | undefined => {
  if (Array.isArray(value)) return value.join(", ");
  return value;
};

const extractRequestContext = (req?: RequestLike): RequestContext | undefined => {
  if (!req) return undefined;

  const headers = req.headers ?? {};
  const forwardedFor = normalizeHeader(headers["x-forwarded-for"]);
  const userAgent = normalizeHeader(headers["user-agent"]);
  const context: RequestContext = {
    method: req.method,
    url: req.originalUrl || req.url,
    ip: req.ip || forwardedFor?.split(",")[0]?.trim(),
  };

  if (userAgent) {
    context.userAgent = userAgent;
  }

  const sanitizedHeaders = sanitizeHeaders(headers as Record<string, unknown>);
  if (sanitizedHeaders) {
    context.headers = sanitizedHeaders;
  }
  if ("body" in req) {
    context.body = sanitizeValue((req as RequestLike & { body?: unknown }).body);
  }

  return Object.values(context).some(Boolean) ? context : undefined;
};

export { generateFingerprint, classifyError, determineSeverity, extractRequestContext };
