const SENSITIVE_KEYS = new Set([
  "authorization",
  "cookie",
  "set-cookie",
  "x-api-key",
  "api-key",
  "apikey",
  "password",
  "token",
  "access_token",
  "refresh_token",
  "secret",
  "signature",
]);

const REDACTED = "[REDACTED]";

const normalizeKey = (key: string): string => key.toLowerCase();

const sanitizeString = (value: string): string => {
  if (!value) return value;
  return value
    .replace(/(bearer\s+)[a-z0-9._\-+/=]+/gi, "$1[REDACTED]")
    .replace(/(token|password|secret|api[_-]?key)\s*[:=]\s*["']?[^"'\s]+/gi, "$1=[REDACTED]");
};

export const sanitizeValue = (value: unknown): unknown => {
  if (typeof value === "string") {
    return sanitizeString(value);
  }

  if (Array.isArray(value)) {
    return value.map((item) => sanitizeValue(item));
  }

  if (value && typeof value === "object") {
    const output: Record<string, unknown> = {};
    for (const [key, entry] of Object.entries(value as Record<string, unknown>)) {
      output[key] = SENSITIVE_KEYS.has(normalizeKey(key)) ? REDACTED : sanitizeValue(entry);
    }
    return output;
  }

  return value;
};

export const sanitizeHeaders = (headers?: Record<string, unknown>): Record<string, unknown> | undefined => {
  if (!headers) return undefined;
  return sanitizeValue(headers) as Record<string, unknown>;
};
