interface ErrorCacheEntry {
  fingerprint: string;
  timestamp: number;
  count: number;
}

const cache = new Map<string, ErrorCacheEntry>();
const DEDUP_WINDOW_MS = 60000; // 1 minute

export function recordFingerprint(fingerprint: string): number {
  const now = Date.now();
  const entry = cache.get(fingerprint);

  if (!entry) {
    cache.set(fingerprint, { fingerprint, timestamp: now, count: 1 });
    return 1;
  }

  if (now - entry.timestamp > DEDUP_WINDOW_MS) {
    entry.timestamp = now;
    entry.count = 1;
    return 1;
  }

  entry.count++;
  return entry.count;
}

export function consumeDuplicateCount(fingerprint: string): number {
  const entry = cache.get(fingerprint);
  if (!entry) return 0;

  const count = entry.count;
  entry.count = 0;
  return count;
}

export function cleanupCache(): void {
  const now = Date.now();
  for (const [key, entry] of cache) {
    if (now - entry.timestamp > DEDUP_WINDOW_MS) {
      cache.delete(key);
    }
  }
}

const cleanupInterval = setInterval(cleanupCache, DEDUP_WINDOW_MS);
cleanupInterval.unref?.();
