import type { ReliabilityClient } from "./ReliabilityClient";
import type { RequestLike } from "./types";

export function createExpressMiddleware(client: ReliabilityClient) {
  return function errorHandler(err: unknown, req: RequestLike, _res: unknown, next: (err?: unknown) => void) {
    client.captureSync(err, req);
    next(err);
  };
}

export function createNestInterceptor(client: ReliabilityClient) {
  return {
    intercept(context: unknown, next: unknown): unknown {
      try {
        return next;
      } catch (err) {
        const req = context && typeof context === "object" && "switchToHttp" in context
          ? (context as { switchToHttp: () => { getRequest: () => RequestLike } }).switchToHttp().getRequest()
          : undefined;
        client.captureSync(err, req);
        throw err;
      }
    },
  };
}

export function createKoaMiddleware(client: ReliabilityClient) {
  return async function koaErrorHandler(ctx: { request: RequestLike }, next: () => Promise<void>) {
    try {
      await next();
    } catch (err) {
      client.captureSync(err, ctx.request);
      throw err;
    }
  };
}

export function createNextjsMiddleware(client: ReliabilityClient) {
  return function nextjsErrorHandler(
    request: { nextUrl: URL; headers: Headers; method: string; body?: unknown },
    response: unknown,
    next: (err?: unknown) => void
  ) {
    const originalJson = (response as { json?: (data: unknown) => void }).json;
    if (originalJson) {
      (response as { json: (data: unknown) => void }).json = function (data: unknown) {
        if (data && typeof data === "object" && "error" in data) {
          const req: RequestLike = {
            method: request.method,
            url: request.nextUrl.pathname,
            originalUrl: request.nextUrl.href,
            headers: Object.fromEntries(request.headers.entries()),
            body: request.body,
          };
          client.captureSync(data.error, req);
        }
        return originalJson.call(response, data);
      };
    }
    next();
  };
}

export function createFastifyPlugin(client: ReliabilityClient) {
  return async function fastifyPlugin(fastify: { setErrorHandler: (handler: (err: Error, req: RequestLike, reply: { send: (data: unknown) => void }) => void) => void }) {
    fastify.setErrorHandler((err, req, reply) => {
      const requestLike: RequestLike = {
        method: req.method,
        url: req.url,
        originalUrl: req.raw?.url,
        headers: req.headers as Record<string, string | string[] | undefined>,
        body: req.body,
        query: req.query,
        ip: req.ip,
      };
      client.captureSync(err, requestLike);
      reply.send(err);
    });
  };
}