import type { DeliveryResult, IngestPayload, ReliabilityConfig } from "./types";

const MAX_RETRIES = 3;
const RETRY_DELAY_MS = 1000;
const DEFAULT_ENDPOINT = "https://api.xecurecode.in/api/v1/ingest";
const SDK_VERSION = "node@0.3.0";

async function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function fetchWithRetry(
  url: string,
  options: RequestInit,
  timeoutMs: number,
  retries: number = MAX_RETRIES
): Promise<DeliveryResult> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, {
      ...options,
      signal: controller.signal,
    });

    if (response.ok) {
      return { ok: true, status: response.status };
    }

    if (response.status >= 500 && retries > 0) {
      await sleep(RETRY_DELAY_MS * (MAX_RETRIES - retries + 1));
      return fetchWithRetry(url, options, timeoutMs, retries - 1);
    }

    return { ok: false, status: response.status };
  } catch (error) {
    if (retries > 0) {
      await sleep(RETRY_DELAY_MS * (MAX_RETRIES - retries + 1));
      return fetchWithRetry(url, options, timeoutMs, retries - 1);
    }
    return {
      ok: false,
      error: error instanceof Error ? error : new Error(String(error)),
    };
  } finally {
    clearTimeout(timeout);
  }
}

function addSdkVersion(payload: IngestPayload): IngestPayload {
  return {
    ...payload,
    sdk_version: SDK_VERSION,
  };
}

export async function sendToBackend(
  payload: IngestPayload,
  config: ReliabilityConfig
): Promise<DeliveryResult> {
  const endpoint = config.endpoint || DEFAULT_ENDPOINT;
  return fetchWithRetry(endpoint, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "xc-api-key": config.apiKey,
      "xc-service-id": config.service_id,
    },
    body: JSON.stringify(addSdkVersion(payload)),
  }, config.timeout ?? 5000);
}

export async function sendBatchToBackend(
  payloads: IngestPayload[],
  config: ReliabilityConfig
): Promise<DeliveryResult> {
  const endpoint = (config.endpoint || DEFAULT_ENDPOINT).replace("/ingest", "/ingest/batch");
  return fetchWithRetry(endpoint, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "xc-api-key": config.apiKey,
      "xc-service-id": config.service_id,
    },
    body: JSON.stringify(payloads.map(addSdkVersion)),
  }, config.timeout ?? 5000);
}